/* Shared quote/rate and promo calculations for all three landing languages.
 * Daily data is generated by scripts/update-market-data.py.
 * Quotes prefer tomorrow in Moscow, then the nearest available date in one week.
 * Neither missing nor stale quotes are replaced with illustrative card prices.
 */
(function(root){
  'use strict';
  const daily=root.TUTU_DAILY_PRICES||{};
  const sampleRate=1.12888;
  const promotions={
    hotel:{percent:15,maxRub:3000,code:'INTHOTELTUTU',end:'2026-12-31'},
    flight:{percent:15,maxRub:1000,code:'INTAVIATUTU',end:'2026-12-31'}
  };
  function moscowDate(){
    const parts=new Intl.DateTimeFormat('en-GB',{
      timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'
    }).formatToParts(new Date());
    const get=type=>parts.find(p=>p.type===type).value;
    return get('year')+'-'+get('month')+'-'+get('day');
  }
  function nextDate(day){
    const d=new Date(day+'T12:00:00Z');
    d.setUTCDate(d.getUTCDate()+1);
    return d.toISOString().slice(0,10);
  }
  const positive=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;
  function rubToInr(){
    const value=Number(daily.fx&&daily.fx.rubToInr);
    return positive(value,0.1,10)?value:sampleRate;
  }
  function quote(type,id){
    const prices=daily.quotes;
    const tomorrow=nextDate(moscowDate());
    if(!['routes','hotels'].includes(type)||
       !prices||prices.currency!=='RUB'||prices.for!==tomorrow)return null;
    const amount=Number(prices[type]?.[id]);
    if(!positive(amount,100,2000000))return null;
    const dated=prices.dates?.[type]?.[id]||tomorrow;
    if(typeof dated!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(dated)||
       dated<tomorrow||dated>addDays(tomorrow,7))return null;
    return {price:amount,date:dated};
  }
  function addDays(day,days){
    const dt=new Date(day+'T12:00:00Z');
    dt.setUTCDate(dt.getUTCDate()+days);
    return dt.toISOString().slice(0,10);
  }
  function basePrice(type,id,_illustrative){return quote(type,id)?.price??null}
  function quoteDate(type,id){return quote(type,id)?.date??null}
  function dateLabel(type,id,lang='ru'){
    return '';
  }
  function discountRub(type,price){
    const promo=promotions[type],amount=Number(price);
    if(!promo||!positive(amount,100,2000000)||moscowDate()>promo.end)return 0;
    return Math.min(Math.round(amount*promo.percent/100),promo.maxRub);
  }
  function reducedRub(type,price){return price-discountRub(type,price)}
  root.TUTU_PRICING={rubToInr,basePrice,quoteDate,dateLabel,discountRub,reducedRub,moscowDate,nextDate,promotions};
})(window);
